window.EW=window.EW||{pages:{}};window.EW.glossary=[{"id":"accord-runique","term":"Accord runique","aliases":["Accords runiques","accords consacrés","Accord consacré","Accords consacrés"],"cat":"Magie","def":"Ensemble de plusieurs runes agissant comme un tout ; plusieurs accords composent une partition.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["runomancie-dico-accords","runomancie-lore"]},{"id":"aerwyn","term":"Aerwyn","aliases":["Maison Aerwyn"],"cat":"Maisons","def":"Fondatrice : Althea Aerwyn. · Couleur : Bleu. · Symbole : le Pégase, accompagné de l'épée et du bouclier.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore"]},{"id":"belladorn","term":"Belladorn","aliases":["Belladorne"],"cat":"Familles","def":"Valeurs connues : Empirisme, Indépendance, Expertise alchimique, Discrétion opérationnelle.","auto":true,"k":"lore-belladorne","a":"joueurs","pages":["lore-belladorne"]},{"id":"brulebrume","term":"Brûlebrume","aliases":["Brulebrume"],"cat":"Lieux","def":"Bien avant de devenir l’un des lieux les plus dangereux et les plus surveillés d’Elderwood, elle n’était qu’une vaste étendue boisée, dense et humide, à l’écart des chemins les plus fréquentés de l’île.","auto":true,"k":"brulebrume","a":"joueurs","pages":["brulebrume"]},{"id":"brumval","term":"Brumval","aliases":["Maison Brumval"],"cat":"Maisons","def":"Fondateur : Hector Brumval. · Couleur : Vert. · Symbole : le Grand Ours.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore"]},{"id":"caerwyn","term":"Caerwyn","aliases":[],"cat":"Familles","def":"Valeurs connues : Honneur, Protection, Droiture, Constance","auto":true,"k":"lore-caerwyn","a":"joueurs","pages":["lore-caerwyn"]},{"id":"catalyseur","term":"Catalyseur","aliases":["Catalyseurs"],"cat":"Objets","def":"Objet (baguette, sceptre, grimoire) canalisant et stabilisant le Flux du sorcier.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["catalyseurs"]},{"id":"choixologue","term":"Choixologue","aliases":["Choixologie"],"cat":"École","def":"fonction et rituel liés à la répartition des maisons.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore"]},{"id":"cristal-coeur","term":"Cristal-Cœur","aliases":["Cristaux-Cœurs","Cristaux-Coeurs","Cristal-Coeur"],"cat":"Objets","def":"Un Cristal-Cœur conserve la Résonance de la créature dont provient l'ingrédient.","auto":true,"k":"cristaux-coeurs","a":"joueurs","pages":["cristaux-coeurs"]},{"id":"dissonant","term":"Dissonant","aliases":["Dissonants","Dissonante","Dissonantes"],"cat":"Magie","def":"Personne née de parents Sans-Flux mais présentant une ou deux mutations magiques rares.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore","lore-hearthbane"]},{"id":"dravenholt","term":"Dravenholt","aliases":[],"cat":"Familles","def":"Valeurs connues : Influence, Élégance, Ambition, Noblesse","auto":true,"k":"maison-dravenholt","a":"joueurs","pages":["maison-dravenholt"]},{"id":"echo","term":"Écho","aliases":["Echo"],"cat":"Magie","def":"Aussi appelé magie, l'origine de toute chose, présente dans l'existence depuis le Premier Murmure.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore","echoide"]},{"id":"echoide","term":"Échoïde","aliases":["Échoïdes","Echoide","Echoïde"],"cat":"Créatures","def":"Souvenir ou connaissance de runomancien figé dans une rune instable ou endommagée.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["echoide","bible-du-lore"]},{"id":"falcon","term":"Falcon","aliases":["Maison Falcon"],"cat":"Maisons","def":"Fondateur : Eldric Falcon. · Couleur : Orange. · Symbole : le Faucon pèlerin.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore"]},{"id":"flux","term":"Flux","aliases":[],"cat":"Magie","def":"Énergie née de la rencontre entre l'Écho et la Résonance, forme perceptible et manipulable de la magie.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore"]},{"id":"hearthbane","term":"Hearthbane","aliases":["Heartbane","Hearthbane"],"cat":"Familles","def":"Valeurs connues : Loyauté, Camaraderie, Générosité, Courage","auto":true,"k":"lore-hearthbane","a":"joueurs","pages":["lore-hearthbane"]},{"id":"intention","term":"Intention","aliases":[],"cat":"Magie","def":"Ce que le sorcier veut faire en lançant son sort.","auto":false,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore"]},{"id":"la-source-de-vehr","term":"La Source de Vehr","aliases":["Source de Vehr"],"cat":"Lieux","def":"Source d'eau révélant la couleur du Flux de chaque individu.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore"]},{"id":"magie-d-usage","term":"Magie d'usage","aliases":["Magie d’usage"],"cat":"Magie","def":"Magie du quotidien, canalisée par l'intention, le geste, l'incantation et le catalyseur.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore"]},{"id":"onde","term":"Onde","aliases":[],"cat":"Magie","def":"Vibration originelle née avec l'univers, à l'origine de l'Écho.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore"]},{"id":"partition","term":"Partition","aliases":["Partitions"],"cat":"Magie","def":"Structure runique complète capable d'orienter durablement le Flux dans un lieu ou un objet.","auto":false,"k":"bible-du-lore","a":"joueurs","pages":["runomancie-lore"]},{"id":"punitions","term":"Punitions","aliases":["Punition"],"cat":"Règles","def":"Les punitions n°6 à 8 ne peuvent être prononcées par la Direction qu’après concertation avec le Directeur de Maison de l’élève concerné, ou son adjoint lorsque celui-ci est indisponible.","auto":false,"k":"reglement-professeurs-30-10-26","a":"joueurs","pages":["reglement-professeurs-30-10-26","reglement-eleves-30-10-26"]},{"id":"ravenscroft","term":"Ravenscroft","aliases":[],"cat":"Familles","def":"Valeurs connues : Expertise runique, Rigueur méthodologique, Préparation, Responsabilité du spécialiste.","auto":true,"k":"maison-ravenscroft","a":"joueurs","pages":["maison-ravenscroft"]},{"id":"razorball","term":"Razorball","aliases":["Razeball","Razorball"],"cat":"École","def":"Sport international sorcier se jouant sur des balais à une centaine de mètres de hauteur, dont le nom peut être dérivé en « Razeball » ou plus communément appelé par les joueurs « Raze ». Codifié à Elderwood par Corvinus Valemont en 1863 (voir 6.5, famille Valemont), avec la création du Vif d'Or. Voir également 6.4 pour la description du Terrain de Razorball et de ses règles de jeu, et 11 (calendrier des événements) pour le tournoi annuel. · 7.6. Autorités liées aux créatures et à la magie · Le Ministère établit et tient à jour la classification officielle des créatures magiques (voir 8.1). Dans les faits, une partie du travail de terrain qui alimente cette classification revient depuis des siècles à la famille Glenhart, dont les deux branches produisent la documentation de référence sur la faune magique britannique, l'une auprès des espèces qui tolèrent la proximité des sorciers, l'autre dans les territoires où elles ne la tolèrent pas (voir 6.5). Sur les structures runiques anciennes et défaillantes, une logique comparable s'applique avec la famille Ravenscroft: le Ministère réglemente, mais ce sont eux qu'on appelle sur le terrain. · Section 8 · · TRANSVERSAL · Les créatures magiques · 8.1. Classification officielle du Ministère de la Magie · Chaque créature magique est répertoriée selon un système de classification officiel établi par le Ministère de la Magie, visant à évaluer la dangerosité et la difficulté de contrôle ou de domestication de chaque espèce. Le Ministère a choisi une échelle graduée composée d'un tiret suivi d'un certain nombre de lettres « A » (exemple : -A-, -AA-, -AAA-, etc.) pour représenter le niveau de dangerosité. Cette notation symbolise le rythme cardiaque et le niveau d'adrénaline que la rencontre avec la créature peut provoquer chez un sorcier ou une sorcière : le tiret et la lettre « A » représentent un battement de cœur, et plus il y a de « A », plus la créature est dangereuse et difficile à maîtriser. · Niveau · Nom · Description · -A- · L'Assent · Créatures peu dangereuses, faciles à apprivoiser ou à contrôler. · -AA- · Dossile · Créatures dociles, avec un faible risque pour les sorciers. · -AAA- · Maîtrisable · Créatures nécessitant une certaine expérience pour être contrôlées, pouvant devenir dangereuses si mal gérées. · -AAAA- · Redoutable · Créatures dangereuses, demandant des compétences avancées et une vigilance constante. · -AAAAA- · Mortel · Créatures extrêmement dangereuses, tueuses de sorciers. · Ce système est utilisé pour guider les interventions, la formation des personnels magiques, et la gestion des créatures dans le cadre du respect des lois magiques et de la sécurité publique. · 8.2. Bestiaire : créatures classées · Gluivern · (-A- L'Assent) · Petite créature magique rampante que l'on trouve principalement dans les zones humides (marécages, sous-bois détrempés, abords de rivières). Corps long d'environ vingt-cinq centimètres, rappelant celui d'une limace épaisse recouverte en permanence d'une bave visqueuse aux couleurs vives, souvent verdâtres ou légèrement bleutées. Malgré son apparence répugnante, il est de faible dangerosité : totalement aveugle, il perçoit son environnement grâce aux vibrations du sol, et craintif, il évite les humains, ne devenant problématique qu'en cas de contact direct. Sa particularité réside dans sa bave, légèrement toxique et naturellement engourdissante : au contact de la peau, elle provoque des picotements, des rougeurs et un engourdissement local temporaire, effets légers disparaissant avec le temps. Une fois récoltée et correctement préparée, cette bave perd en grande partie son caractère irritant tout en conservant ses propriétés anesthésiantes, permettant d'endormir une zone plus étendue pour des soins simples ou interventions mineures ; mal préparée, elle peut au contraire provoquer une irritation plus marquée et un engourdissement instable. Se nourrit principalement de matières végétales en décomposition et laisse des traces glissantes. · Item drop : Bave de Gluivern. · Pattibole · (-A- L'Assent) · Petite créature fongique des sols humides, sous-bois ombragés et terrains riches en matière organique. Corps massif et arrondi dominé par un large chapeau épais en forme de dôme, surface lisse mais irrégulière aux teintes sombres mêlées de violet, de brun et de rosé. Sous ce chapeau, corps compact porté par quatre petites pattes courtes lui permettant des déplacements rapides par bonds ou en se glissant entre pierres et racines. Inoffensif pour les sorciers comme pour les animaux, mais devient pénible lorsqu'il s'installe dans une zone cultivée. Peureux, il fuit au moindre danger, ce qui le rend difficile à attraper. Lorsqu'il se sent menacé, il laisse échapper un liquide urinaire clair, récolté par certains sorciers comme ingrédient de potions curatives, et peut détaler brusquement pour se réfugier sous terre, dans les serres ou entre les plantations, où il dérange les cultures. Se nourrit principalement de matière végétale en décomposition et de nutriments des sols humides ; sa prolifération rapide en fait une gêne bien connue des jardiniers, herboristes et habitants des régions marécageuses. · Item drop : Urine de Pattibole. · Brisecerat · (-A- L'Assent) · Petite créature magique côtière rencontrée entre la mer, les plages rocheuses et les lacs bordés de sable ou de galets. Corps compact et bas sur pattes, évoquant une petite bête blindée recouverte d'une cératine naturelle formant plusieurs plaques souples mais résistantes sur son dos, lui permettant de se fondre dans les rochers humides, le sable mouillé et les herbes de bord d'eau. Discret et farouche, il évite la présence humaine et préfère rester à l'abri dans les anfractuosités de roche, les zones de ressac ou les berges tranquilles, devenant défensif uniquement s'il se sent acculé ou si son nid est dérangé. Sa particularité réside dans sa cératine, matière naturelle très recherchée dans le monde magique : une fois prélevée et traitée, elle sert à fabriquer des vêtements de protection de deuxième facture (manteaux, pantalons, gants renforcés), moins résistante que la peau de dragon mais au-dessus du cuir renforcé classique, offrant un bon compromis entre souplesse, solidité et prix abordable. Se nourrit principalement de petites algues, de coquillages ramollis, de mousses salées et de matières organiques déposées par la mer. · Item drop : Cératine de Brisecerat. · Scalvignus · (-AA- Dossile) · Créature des forêts denses composées de très grands arbres (sol britannique, Europe, certaines forêts d'Amérique du Nord autour des séquoias). Silhouette rappelant celle d'un cerf, corps recouvert d'écailles lisses et résistantes, bois larges et ramifiés (excroissances osseuses temporaires tombant naturellement à la fin de l'hiver, comme chez les cervidés). Créature discrète et prudente, évitant les humains, se déplaçant silencieusement entre les arbres ; utilise ses bois principalement pour se défendre contre les prédateurs ou lors d'affrontements territoriaux. Nature calme et docile lui permettant de coexister avec d'autres espèces, à condition de ne pas être provoqué. Sa particularité réside dans ses bois, utilisés comme cœur de baguette dans le monde magique, jamais prélevés en tuant la créature de manière légale, mais récupérés une fois tombés naturellement au sol à la fin de l'hiver ; plusieurs grandes réserves et parcs forestiers sont protégés par des enchantements magiques et surveillés par des zoologistes spécialisés organisant la récolte durable. Ce cœur confère à la baguette deux propriétés majeures : une magie défensive renforcée et un bonus important sur les sorts de botanique. · Item drop : Bois de Scalvignus. · Ornicabal · (-AAA- Maîtrisable) · Créature semi-aquatique des forêts riveraines, appartenant à la famille des équidés, avec des traits rappelant aussi les reptiles et les oiseaux. Peau recouverte de très petites écailles fines, texture lisse mais un peu rugueuse au toucher, solide et hydrophobe, lui permettant de rester au sec malgré son environnement humide. Tête possédant un bec corné semblable à celui des oiseaux, utilisé pour attraper les poissons (sa principale nourriture), et des cornes recourbées sur la tête. Comportement d'agressivité conditionnelle : pas systématiquement agressif, mais peut devenir dangereux lorsqu'il défend son territoire ou ses ressources alimentaires, utilisant alors toute sa force sans vraiment se rendre compte de sa puissance. Malgré cela, sociable et joueur, aimant courir et nager avec d'autres Ornicabals ; peut être apprivoisé et devenir un compagnon fidèle, mais son côté impulsif demande patience et prudence. L'Ornicabal mue naturellement en grandissant, perdant sa peau écailleuse : cette mue est très recherchée pour fabriquer des vêtements et équipements résistants à l'eau utilisés par les magizoologistes, et sert également de cœur de baguette augmentant l'affinité avec la magie à base d'eau. · Item drop : Mue de l'Ornicabal. · L'Echomys · (classification à préciser) · Petite créature magique ronde et touffue, mesurant entre vingt et trente centimètres de hauteur. Corps compact recouvert d'un pelage épais composé de fines couches végétales ou cristallines selon sa couleur de Flux, grands yeux sombres, petites pattes griffues permettant des déplacements par bonds courts et silencieux. Reconnaissable à ses deux ramures frontales semblables à de petites branches ou excroissances cristallines, et à sa queue plumeuse servant d'équilibre et d'outil de communication. Surtout connu pour son lien exceptionnel avec l'Onde, percevant les vibrations magiques avec une finesse rare : on le trouve fréquemment près des sources magiques, sanctuaires oubliés, ruines druidiques et lieux où l'Écho demeure particulièrement fort, plus un endroit est chargé en résonance, plus les colonies y sont nombreuses. Communique par de faibles vibrations, presque inaudibles pour l'oreille humaine, se propageant dans l'air, le sol et parfois l'eau proche. Il existe plusieurs teintes d'Echomys associées aux couleurs du Flux (vert, bleu, violet, orange) ainsi qu'une variante noire extrêmement rare, chaque couleur influençant légèrement son comportement et son lieu de prédilection. Paisibles, curieux et rarement agressifs, ils privilégient les grandes sources magiques et zones à forte résonance ; leur apparition auprès d'un sorcier indique souvent que celui-ci dégage une résonance suffisamment forte pour attirer leur attention. · Le Sami · (classification à préciser) · Petite créature magique quadrupède, souvent comparée à un rat ou un furet trapu, mesurant entre 25 et 40 centimètres pour un poids rarement supérieur à quelques kilos. Corps bas et compact, membres courts adaptés aux déplacements rapides dans les fissures, racines, caves et anciens bâtiments. Trouvé principalement dans les lieux chargés de magie ancienne (abords d'écoles, ruines, forêts humides, vieilles serres, souterrains, murs de pierre) ; à Elderwood, vit surtout dans les zones peu fréquentées du château et à la lisière de la forêt, construisant ses nids avec feuilles sèches, morceaux de tissu, fragments de bois et parfois de petits objets imprégnés de magie. Créature non agressive, évitant les humains, mais pouvant mordre si attrapée ou acculée ; se nourrit principalement d'insectes, de racines, de petits champignons et de résidus magiques présents dans certains matériaux anciens, ce qui explique sa présence fréquente dans les lieux où des sorts ont été lancés pendant de nombreuses années. Sa principale capacité vient de sa sensibilité aux variations de Résonance : il ne pratique pas la magie mais perçoit les zones instables avant la plupart des sorciers, changeant brusquement de comportement (grattant les murs, quittant son nid, se regroupant, refusant d'entrer dans certaines pièces) lorsqu'un lieu devient dangereux ou perturbé. Certains professeurs d'Elderwood considèrent sa présence comme un indicateur discret de l'état magique d'un lieu. · Depuis les événements récents sur l'île · (voir section · 9), les Sami ont été observés dans des zones inhabituelles du château, et leur déplacement soudain est pris au sérieux par le personnel, ces créatures réagissant rarement sans raison. · Les Arachnides d'Éther et la Tisseuse Primordiale · 🖼️ Emplacement image, Arachnides d'Éther · Voir section · 5.4 · (Brûlebrume) pour la description complète de cette espèce et de l'entité qui y est associée. · Section 9 · · LORE MODERNE · Les événements précédant la rentrée · 9.1. Résumé des faits (points clés) · Coup d'État raté mené par l'Ascendance contre le Ministère de la Magie. · Plusieurs morts, dont l'ancien directeur d'Elderwood (Arthurius Glenwood) et plusieurs professeurs. · Nouvelle direction (Dravenholt) et nouveaux professeurs à Elderwood pour la rentrée. · Contexte tendu : le Voile d'Elderwood est « tombé en panne » et l'île a été révélée à un groupe de personnes sur un bateau, qui l'ont filmée et publiée sur les réseaux sociaux. · Une tendance virale sur les réseaux autour de cette nouvelle légende urbaine a lancé une vague de Sans-Flux à la recherche de l'île cachée. · L'Ascendance se sont réfugiés dans des ruines d'Elderwood, y apposant un voile artificiel, cause du dérèglement momentané du Voile de l'île. · La cohabitation avec les Sans-Flux devient de plus en plus complexe pour les Résonants. · 9.2. Récit chronologique détaillé · La majeure partie de ce récit est connue des joueurs à la rentrée (voir la répartition exacte en 11.3) ; seuls les passages explicitement encadrés comme lore staff ne le sont pas. · À Elderwood, les anciens aiment dire que le château se souvient mieux que les hommes. Les générations passent, les noms changent, les lignées montent ou s'éteignent, mais les pierres demeurent, chargées de tout ce qu'elles ont vu. Les élèves apprennent cela bien avant de comprendre leurs premiers sorts : à Elderwood, rien ne disparaît vraiment. Cette année plus que les autres, cette vérité semble s'imposer à tous. · Depuis plusieurs années, un groupe extrémiste connu sous le nom des l'Ascendance mène des actions de plus en plus visibles dans le monde magique britannique. Au départ, beaucoup les considéraient comme une menace secondaire, composée de sorciers radicaux opposés à la place croissante des Sans-Flux dans les décisions du monde magique. Avec le temps, leurs actions se sont durcies : sabotages, intimidations, vols de documents, usage de magies interdites, menaces contre des familles mixtes, attaques ciblées contre certains Dissonants, l'Ascendance ont cessé d'être un simple courant d'opinion pour devenir une organisation structurée. · Leur idéologie repose sur une idée simple : le monde magique ne devrait plus vivre caché ni se plier à l'existence des Sans-Flux. Pour eux, les Sans-Flux représentent une menace politique, culturelle et sociale ; les Dissonants sont perçus comme un signe de dérèglement, une anomalie remettant en cause les anciennes certitudes liées au Flux et aux lignées magiques. Ce discours reste minoritaire, mais gagne du terrain auprès de certains sorciers, surtout depuis que les relations entre les deux mondes sont devenues plus difficiles à maintenir. L'Ascendance exploitent cette peur : ils ne cherchent pas seulement à convaincre, ils cherchent à créer les conditions d'un basculement. · Face à cette menace, · Arthurius Glenwood, directeur d'Elderwood, comprit que le Ministère ne voyait pas encore toute l'ampleur du problème : l'Ascendance n'agissaient pas seulement depuis l'extérieur, ils infiltraient des services, des journaux, des familles influentes et certaines institutions liées à l'éducation magique. Des rumeurs, jamais confirmées, évoquent qu'il aurait réuni autour de lui plusieurs alliés du monde magique pour y faire face (voir 7.3). · Six mois avant la rentrée, le Ministère annonça ce qui sembla être une grande victoire : plusieurs membres de l'Ascendance infiltrés furent identifiés, arrêtés ou contraints de fuir, déjouant ce qui fut présenté comme une tentative de renversement du gouvernement magique avant même qu'elle ne puisse commencer. L'opinion publique y vit la preuve que l'Ascendance avaient été frappés au cœur de leur réseau. · Après cette fausse victoire, Arthurius continua d'enquêter, sentant que trop d'éléments ne correspondaient pas : des accès utilisés par l'Ascendance n'avaient jamais été expliqués, plusieurs documents saisis semblaient volontairement incomplets, des noms revenaient dans les rapports sans jamais pouvoir être reliés à des preuves solides. Il comprit que le réseau actif était encore en place, et qu'Elderwood, lieu ancien, protégé par des défenses uniques, lié à la Source, au Voile, aux Flux et à plusieurs espaces magiques que peu de sorciers comprenaient réellement, pouvait devenir une cible. · C'est dans ce contexte qu'un piège fut tendu à Arthurius et à son entourage. L'Ascendance firent circuler une information selon laquelle un de leurs relais internes était prêt à transmettre des preuves capables d'identifier les véritables responsables du mouvement. Arthurius réunit alors plusieurs proches collaborateurs à Elderwood, après la fin des cours ; le rendez-vous devait rester discret. Des professeurs quittèrent leurs salles séparément avant de rejoindre la cour du grand arbre, puis le directeur les conduisit vers un lieu de réunion situé en bordure de la forêt, où d'autres personnes les attendaient déjà. · La rencontre fut une embuscade. L'Ascendance avaient préparé l'affrontement et connaissaient une partie des habitudes de ce cercle. Les combats commencèrent dans la forêt avant de se déplacer vers l'école. Plusieurs personnes furent tuées sur place ; d'autres réussirent à se replier vers le château, mais l'Ascendance avaient déjà prévu d'attaquer Elderwood directement. Plusieurs accès furent forcés, certains depuis l'intérieur, prouvant que l'organisation disposait encore d'informations précises sur les défenses de l'école. Les alarmes runiques se déclenchèrent trop tard pour empêcher l'intrusion complète. · L' · attaque d'Elderwood fut courte, mais lourde de conséquences. Plusieurs membres du corps professoral moururent en tentant de défendre l'école ; des salles furent détruites, des protections anciennes endommagées, et certaines zones du château durent être fermées dès le lendemain. · Arthurius Glenwood fut grièvement blessé pendant l'affrontement, puis assassiné avant que les secours ne puissent le sauver. Sa mort marqua un tournant : pour les élèves, la disparition d'un directeur respecté ; pour l'Ascendance, une étape nécessaire avant leur véritable objectif. · Peu après l'attaque d'Elderwood, l'Ascendance lancèrent leur véritable tentative de coup d'État contre le Ministère de la Magie britannique, non plus par une cellule sacrifiable, mais par les relais restés cachés après la première fausse défaite. · Le Ministre de la Magie fut assassiné durant l'attaque. Sa mort provoqua un choc immédiat dans tout le monde magique ; pendant plusieurs heures, l'avenir du gouvernement resta incertain, certains services paralysés, d'autres infiltrés, plusieurs décisions contradictoires circulant avant que les forces restées loyales au Ministère ne reprennent le contrôle. · Le coup d'État échoua, mais son échec ne suffit pas à effacer ses conséquences : le Ministère venait de perdre son dirigeant, plusieurs de ses agents, une partie de sa crédibilité et la certitude que ses propres structures étaient sûres. Des arrestations eurent lieu, mais beaucoup de questions restèrent sans réponse : combien de l'Ascendance avaient fui ? Combien étaient encore en poste sous une autre identité ? Qui avait réellement permis l'accès aux zones protégées du Ministère ? Et depuis combien de temps le mouvement préparait-il cette attaque ? · Pendant que le Ministère gérait les conséquences du coup d'État, un autre problème apparut à Elderwood : · le Voile qui protège l'île des regards Sans-Flux connut une rupture. Certains pensèrent d'abord à une conséquence indirecte des combats à l'école ; l'enquête révéla ensuite une piste plus inquiétante. L'Ascendance auraient trouvé une cachette sur l'île, à proximité d'un lieu magique ancien et puissant, et pour la dissimuler, ils auraient modifié localement les protections avec des runes afin de rendre cet espace invisible même aux sorciers qui ne savaient pas quoi chercher. Cette intervention a perturbé l'équilibre du Voile : les runes utilisées n'ont pas seulement masqué leur cachette, elles ont interféré avec une protection beaucoup plus vaste que l'Ascendance ne maîtrisaient pas entièrement. Pendant un court instant, l'île d'Elderwood est devenue visible depuis l'extérieur. Un bateau de plaisance passant trop près des côtes aperçut les falaises, les tours du château et des traces de magie encore présentes dans le ciel. Les passagers filmèrent ce qu'ils voyaient. · Les images furent publiées avant que le Ministère ne puisse intervenir. · En temps normal, le Ministère aurait probablement contenu l'incident plus vite, mais les attaques récentes, la mort du Ministre et la crise interne ralentirent la réponse. Les vidéos circulèrent, furent sauvegardées, copiées et commentées par des milliers de Sans-Flux avant que les services de dissimulation ne puissent agir efficacement. Certains parlèrent de montage, d'autres d'une base militaire, d'un phénomène naturel ou d'une île inconnue ; mais pour une partie du public Sans-Flux, l'idée qu'un lieu caché existe réellement commença à s'installer. Le problème n'était plus seulement magique : les machines Sans-Flux conservaient des traces que les sorts d'effacement ne pouvaient pas toujours supprimer à temps. Des forums se remplirent de cartes anciennes, de récits oubliés, de trajectoires maritimes recoupées avec une obsession presque maladive ; des groupes se formèrent, décidés à retrouver cette terre que personne n'était censé connaître. · Cette exposition renforça aussi les tensions internes du monde magique. L'Ascendance avaient échoué à prendre le pouvoir, mais leurs idées commencèrent à circuler davantage. Certains sorciers, choqués par la diffusion des vidéos et par l'incapacité du Ministère à protéger le secret magique, commencèrent à reprendre une partie de leur discours, sans forcément soutenir les crimes commis, mais estimant que l'Ascendance avaient au moins posé une question que le Ministère refusait de traiter : combien de temps le monde magique pouvait-il encore se cacher alors que le monde Sans-Flux enregistrait tout ? · À Elderwood, les conséquences furent immédiates : toute technologie Sans-Flux est désormais confisquée dès l'arrivée, les contrôles ont été renforcés, les rondes nocturnes multipliées, et plusieurs zones du domaine restent interdites aux élèves. Certaines parties du château portent encore les traces de l'attaque : dans l'aile orientale, plusieurs vitraux n'ont pas été remplacés ; des portraits ont été retirés, officiellement pour restauration, même si beaucoup savent qu'ils ont cessé de parler depuis cette nuit-là ; les escaliers menant aux anciennes salles de recherche restent fermés, et les professeurs évitent de répondre lorsqu'on leur demande ce qui s'y trouve encore. · C'est dans ce climat que · Dravenholt a pris la direction de l'école, nommée dans l'urgence après la mort d'Arthurius Glenwood. Elle hérite d'un établissement affaibli, surveillé par le Ministère et encore marqué par la perte d'une partie de son corps professoral. De nouveaux professeurs ont été appelés pour combler les places laissées vides ; certains arrivent avec une réputation solide, d'autres semblent avoir été choisis parce que les circonstances ne permettaient pas d'attendre. Les élèves sentent bien que cette rentrée n'est pas comme les autres, même lorsque les adultes prétendent que l'école doit simplement reprendre son cours. · À cela s'ajoute l'évolution des Dissonants, dont le nombre semble augmenter et les profils se diversifier (voir 1.5). · 9.3. Ce qu'on retient de cette période · Les joueurs savent, à la rentrée : l'existence de l'Ascendance et de leurs actions violentes ; la mort de l'ancien directeur Arthurius Glenwood et de plusieurs professeurs lors d'une attaque d'Elderwood ; l'assassinat du Ministre de la Magie et l'échec du coup d'État ; la rupture du Voile et la diffusion publique de vidéos de l'île ; l'existence du Cercle du Frêne dans ses grandes lignes officieuses ; la nomination de Dravenholt à la tête de l'école ; le durcissement général des règles (confiscation des technologies Sans-Flux, rondes renforcées, zones fermées). · Section 10 · · LORE MODERNE · Situation actuelle du monde · Cette section sert de référence pour écrire les quêtes, dialogues, événements et réactions des personnages non-joueurs au lancement du serveur. · 10.1. La vie quotidienne à Elderwood · À Elderwood, les élèves comprennent vite que l'école n'est pas un simple internat. Le château est ancien, chargé d'histoire, et beaucoup d'habitudes se transmettent entre élèves bien plus que par les professeurs. On apprend où passer, quels lieux éviter à certaines heures, quels comportements attirent inutilement l'attention. Les nouveaux se laissent guider par les plus anciens, qui leur montrent les chemins sûrs, les salles où l'on ne s'attarde pas seul et les petites traditions propres à chaque maison. Le château lui-même impose son respect : on évite de forcer une vieille porte, de provoquer un portrait, de crier dans certaines ailes ou de toucher aux objets qui semblent oubliés là depuis longtemps. Rien ne prouve vraiment que ces gestes soient dangereux ; à Elderwood, on préfère simplement ne pas vérifier. · Depuis l'été dernier, certains sujets se traitent avec plus de prudence. Les disparitions, les professeurs remplacés, l'Ascendance, les Dissonants, les failles du Voile reviennent dans les conversations, souvent à voix basse. L'école s'efforce de reprendre son rythme, sans effacer tout à fait cette impression que la rentrée pèse plus lourd que les précédentes. · La journée à Elderwood se règle moins sur les horloges que sur les Carillons: un tintement clair ouvre les cours, une note plus grave annonce le couvre-feu, une vibration plus longue prévient qu'un avis vient d'être affiché. Les cours occupent le gros des journées, magie d'usage, soins, créatures, runomancie et le reste, chacun avec sa réputation propre. Les Sabliers de Salle égrènent le temps des exercices sur le bureau des professeurs. Les repas se prennent dans la Grande Salle, où se lit le mieux l'état des maisons : chacune a ses tables, ses habitudes, ses places que personne n'a jamais attribuées et que tout le monde respecte. Le soir, chacun regagne sa salle commune (voir section 4 pour le détail de chacune), où l'on ne vit pas la même soirée d'une maison à l'autre. · Les règles tiennent autant de l'écrit que de l'habitude. Le couvre-feu se respecte parce que les couloirs, la nuit, ne sont pas tout à fait les mêmes que le jour. Certaines zones restent fermées, même aux plus anciens, sans que personne ne demande plus pourquoi. Depuis l'été 2026, le cadre s'est resserré : la technologie des Sans-Flux est confisquée dès l'arrivée, les rondes de nuit se sont multipliées, les hiboux officiels traversent le ciel de l'île plus souvent qu'avant, porteurs d'ordres et de noms que personne ne lit devant les élèves. Nul n'a vraiment expliqué ce durcissement ; chacun en devine la raison. · Certains jours rompent ce rythme : une épreuve entre maisons, une cérémonie, une sortie encadrée se sentent venir avant même de commencer. La Coupe des Quatre Maisons tient l'école en haleine des semaines durant. Ces journées-là, Elderwood ressemble presque à une école ordinaire, bruyante et fière, le temps qu'on oublie un instant ce que la rentrée traîne derrière elle. · 10.2. Les relations entre les maisons · Les quatre maisons d'Elderwood ne sont pas ennemies : elles ne regardent simplement pas le monde de la même façon. Chacune porte une manière d'agir, de réfléchir et de réagir face aux difficultés, et ces écarts nourrissent les rivalités, les moqueries, les alliances inattendues et, parfois, de vraies tensions entre élèves. · On reproche souvent aux Aerwyn leur droiture un peu raide, cette habitude d'agir de front là où un peu de discrétion éviterait bien des ennuis, le reproche venant volontiers des Venatrix, dont les méthodes plus feutrées inquiètent en retour les Aerwyn, qui les jugent trop calculées. Les Falcon veulent comprendre avant d'agir, quitte à paraître distants pendant que les autres tranchent déjà. Les Brumval, attachés au groupe et à la loyauté, passent à l'inverse pour trop sentimentaux aux yeux de ceux qui préfèrent garder la tête froide. · Ces frictions ne dessinent pas deux camps figés : selon les cours, les compétitions ou l'épreuve du moment, les rapprochements se défont et se refont. C'est sur cette complémentarité qu'Elderwood tient. Cette année, l'ambiance est plus tendue qu'à l'ordinaire : les débats autour des Dissonants, la méfiance envers certaines familles anciennes et le climat d'insécurité poussent une partie des élèves à se replier sur leur maison ; d'autres cherchent au contraire à resserrer les liens entre les groupes, convaincus qu'Elderwood ne tiendra qu'en gardant ses maisons capables d'agir ensemble. · 10.3. Anecdotes et légendes du château (à utiliser en jeu) · Le couloir qui connaît les surnoms. · Parmi les rumeurs les plus tenaces d'Elderwood : si une voix vous appelle dans un couloir vide, on ne répond pas. Elle devient plus troublante quand la voix emploie un surnom, un prénom d'enfance ou une façon de parler que seuls des proches devraient connaître. Certains y voient un simple écho laissé dans la pierre par les générations passées ; d'autres jurent que certains couloirs répètent ce qu'ils ont entendu autrefois, sans toujours savoir à qui ces mots appartenaient. Personne ne sait vraiment ce qui arrive à ceux qui répondent. · La salle qui garde les retardataires. · Une vieille histoire circule, celle d'une salle que personne ne retrouve deux fois au même endroit, apparaissant surtout à ceux qui sont perdus, épuisés ou en retard, sous la forme d'une pièce calme, éclairée par un feu doux, meublée comme si elle attendait quelqu'un. Ceux qui y entrent racontent souvent la même chose : ils comptaient s'arrêter quelques minutes, et en ressortant, découvrent que plusieurs heures ont passé. Les anciens conseillent de ne jamais entrer dans une salle inconnue sous prétexte qu'elle a l'air accueillante. · 10.4. Le calendrier des événements de l'année · Événement · Période IG · Fréquence · Lieu · La Rentrée scolaire, répartition à la Source · 1er septembre · Annuelle · Gare, lac, Grande Salle · La Soirée des Masques, anniversaire de Venatrix · 1er novembre · Annuelle · Maison Venatrix · Le Marché des Curiosités Magiques · Début décembre · Annuelle · Cour intérieure · Noël · Fin décembre · Annuelle · Grande Salle · Le Bal d'Elderwood · 12 janvier · Annuelle · Grand Hall · La Nuit de l'Observatoire, anniversaire de Falcon · Solstice d'hiver · Annuelle · Tour de l'Observatoire (Falcon) · Les Joutes d'Honneur, anniversaire d'Aerwyn · Premier samedi de mars · Annuelle · Cour d'armes extérieure · Le Festin des Portes Ouvertes, anniversaire de Brumval · Dernier dimanche d'avril · Annuelle · Maison Brumval · La Flamme Ouverte · Printemps, années paires · Bisannuelle · Devant la maison Brumval · Le Tournoi de Razorball, phase finale · Mai (dernier week-end) · Annuelle · Terrain de Razorball · La Nuit du Départ · Dernière nuit de l'année scolaire · Annuelle · Grande Salle puis château · La Rentrée scolaire. · « Tout le monde arrive étranger. Personne ne repart sans appartenir à quelque chose. » · Les élèves arrivent en train jusqu'à la gare la plus proche d'Elderwood, puis traversent le lac en barque pour rejoindre le château, anciens élèves d'un côté, nouveaux de l'autre. À l'arrivée, les nouveaux sont conduits à la Grande Salle puis à la Source (voir 5.2) pour la répartition. · La Soirée des Masques. · « Ce que tu montres dit moins sur toi que ce que tu choisis de cacher. » · Les élèves de Venatrix portent leur masque toute la journée, du matin au soir, non un déguisement, mais une posture. · Le Marché des Curiosités Magiques. · « Ce que tu cherches, tu ne savais pas encore que tu le cherchais. » · Marchands, artisans et collectionneurs investissent la cour intérieure autour de l'arbre rouge pour une journée ; le soir, une vente aux enchères informelle rassemble des objets singuliers, dont certains dont on se demande comment ils ont quitté les archives ministérielles. · Le Bal d'Elderwood. · Le plus beau bal du calendrier ; les Dravenholt organisent la décoration, la musique et, ce qu'on sait moins, la liste des invités, certains recevant des invitations spéciales les orientant vers certaines salles, certaines conversations. · La Nuit de l'Observatoire. · « Comprendre les étoiles, c'est comprendre les lois que personne n'a écrites. » · Les élèves de Falcon portent sur eux l'objet qui leur a le plus servi intellectuellement dans l'année. En fin de journée, les volontaires montent à l'Observatoire pour partager une observation, une théorie ou une légende. À minuit, deux minutes de silence complet. · Les Joutes d'Honneur. · « La valeur ne se déclare pas. Elle se démontre. » · Seul événement où le duel magique est non seulement autorisé mais célébré, entre élèves d'Aerwyn de même année ou d'année supérieure, en trois passes, sortilèges non létaux, arbitre obligatoire. · Le Festin des Portes Ouvertes. · « Le foyer ne vous appartient pas. C'est vous qui lui appartenez. » · Les élèves de Brumval ne portent pas leur uniforme ce jour-là, en tenue libre intentionnellement décontractée. · La Flamme Ouverte. · Voir · 6.5 · (famille Hearthbane) pour le récit complet de ce festival bisannuel. · Le Tournoi de Razorball, phase finale. · « Le terrain dit ce que la salle de classe tait. » · La saison court toute l'année avec un match mensuel par maison ; la finale de mai est l'événement sportif le plus ouvert du calendrier. La Remise du Vif d'Or Memorial récompense l'Attrapeur à la performance la plus remarquable de la saison. · La Nuit du Départ. · « Elderwood ne vous appartient pas. Mais une partie de vous lui appartient, maintenant. » · Ce n'est pas une fête officielle, mais une tradition née organiquement, jamais formalisée. Le soir des derniers examens, la Grande Salle est ouverte pour un dernier repas libre ; les élèves de septième année, ceux qui partent définitivement, se lèvent en premier et posent un objet, n'importe lequel, pas nécessairement précieux, mais quelque chose de vrai, sur la grande table centrale. Les objets restent sur la table jusqu'au lendemain matin ; personne n'y touche pendant la nuit. · 10.5. Tensions et tendances actuelles · Le climat de suspicion générale envers les technologies Sans-Flux et les zones fermées du château. · La montée du discours de l'Ascendance, y compris chez des sorciers ne soutenant pas leurs crimes mais partageant leur inquiétude sur la soutenabilité du secret magique. · La diversification et l'augmentation du nombre de Dissonants, perçue soit comme une évolution naturelle de l'Écho, soit comme un dérèglement inquiétant selon les familles. · Les tensions sportives historiques entre Valemont et Caerwyn autour du Razorball (voir 6.5). · L'attention discrète que plusieurs grandes familles portent aux Nocteran, dont l'influence réelle reste impossible à mesurer (voir 6.5). · La querelle jamais refermée entre les branches Éleveurs et Chasseurs de la famille Glenhart, ravivée par les disparitions de Shedwood de l'été 2026 (voir 6.5). · Les dérèglements persistants du Voile depuis l'attaque, dont l'origine exacte n'a toujours pas été établie. · Le rôle encore flou de la nouvelle directrice Dravenholt, dont le lien exact avec la famille notable homonyme reste à préciser. · Section 11 · · TRANSVERSAL · Annexes · Annexe A : Chronologie condensée · Voir la section · 2 · (Chronologie générale) pour le tableau complet. Repères majeurs : Fondation d'Elderwood (1300) · Sentence de Mireille (1432) · Flamme Ouverte (1463) · Grande Division des Glenhart (1650) · Loi sur la Pureté Botanique et fondation de La Chaudronnerie (1685) · Disparition de Serafael Nocteran (1754) · Codification du Razorball (1863) · Incident Pryce et expédition de Shedwood (1890) · Serment des Tranchées (1914-1918) · Grand Confinement (1944-1945) · Attaque d'Elderwood et coup d'État de l'Ascendance (été 2026) · Rentrée actuelle (2026). · Annexe B : Glossaire · Écho, Aussi appelé magie, l'origine de toute chose, présente dans l'existence depuis le Premier Murmure. · Onde, Vibration originelle née avec l'univers, à l'origine de l'Écho. · Résonance, Réponse propre de chaque être vivant à l'Écho. · Résonant, Sorcier dont la Résonance permet de produire un Flux exploitable. · Flux, Énergie née de la rencontre entre l'Écho et la Résonance, forme perceptible et manipulable de la magie. · Sans-Flux, Humains dont la Résonance est trop faible pour produire un Flux exploitable. · Dissonant, Personne née de parents Sans-Flux mais présentant une ou deux mutations magiques rares. · Voile, Phénomène local (ou sort) dissimulant un lieu chargé de Flux aux perceptions des Sans-Flux. · Échoïde, Souvenir ou connaissance de runomancien figé dans une rune instable ou endommagée. · Magie d'usage, Magie du quotidien, canalisée par l'intention, le geste, l'incantation et le catalyseur. · Runomancie, Magie ancienne inscrivant le Flux dans la durée à travers des runes. · Catalyseur, Objet (baguette, sceptre, grimoire) canalisant et stabilisant le Flux du sorcier. · Intention, Ce que le sorcier veut faire en lançant son sort. · La Source de Vehr, Source d'eau révélant la couleur du Flux de chaque individu. · Choixologue / Choixologie, fonction et rituel liés à la répartition des maisons. · Accord runique, Ensemble de plusieurs runes agissant comme un tout ; plusieurs accords composent une partition. · Partition, Structure runique complète capable d'orienter durablement le Flux dans un lieu ou un objet. · Résonance de Souffle, Sensibilité du Flux propre à la lignée Glenhart, réagissant à certaines zones et à certaines traces. · La Chaudronnerie, Manoir alchimique des Belladorn, dissimulé sous Voile naturel en banlieue de Londres. · Codex Absinthium, Grimoire alchimique familial des Belladorn, scellé par le sang. · Razorball, Sport international sorcier, aussi appelé « Razeball » ou, familièrement, « le Raze »","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore"]},{"id":"resonance","term":"Résonance","aliases":["Résonances"],"cat":"Magie","def":"Réponse propre de chaque être vivant à l'Écho.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore"]},{"id":"resonance-de-souffle","term":"Résonance de Souffle","aliases":[],"cat":"Magie","def":"Sensibilité du Flux propre à la lignée Glenhart, réagissant à certaines zones et à certaines traces.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore"]},{"id":"resonant","term":"Résonant","aliases":["Résonants","Résonante","Résonantes","Resonant"],"cat":"Magie","def":"Sorcier dont la Résonance permet de produire un Flux exploitable.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore"]},{"id":"runomancie","term":"Runomancie","aliases":["Runomancien","Runomanciens","Runomancienne"],"cat":"Magie","def":"Magie ancienne inscrivant le Flux dans la durée à travers des runes.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["runomancie-lore","runomancie-dico-accords"]},{"id":"sans-flux","term":"Sans-Flux","aliases":[],"cat":"Magie","def":"Humains dont la Résonance est trop faible pour produire un Flux exploitable.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore"]},{"id":"shedwood","term":"Shedwood","aliases":[],"cat":"Lieux","def":"L'objectif principal de Shedwood est d'être créateur de RP.","auto":true,"k":"shedwood","a":"joueurs","pages":["shedwood"]},{"id":"valemont","term":"Valemont","aliases":[],"cat":"Familles","def":"Valeurs connues : Savoir, Curiosité, Sagesse","auto":true,"k":"maison-valemont","a":"joueurs","pages":["maison-valemont"]},{"id":"validation-de-la-direction","term":"Validation de la Direction","aliases":[],"cat":"Règles","def":"À partir de 25 points nécessitent obligatoirement une validation de la Direction.","auto":false,"k":"reglement-professeurs-30-10-26","a":"joueurs","pages":["reglement-professeurs-30-10-26"]},{"id":"venatrix","term":"Venatrix","aliases":["Maison Venatrix"],"cat":"Maisons","def":"Fondatrice : Selena Venatrix. · Couleur : Violet. · Symbole : la Pieuvre Géante.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore"]},{"id":"voile","term":"Voile","aliases":[],"cat":"Magie","def":"Phénomène local (ou sort) dissimulant un lieu chargé de Flux aux perceptions des Sans-Flux.","auto":true,"k":"bible-du-lore","a":"joueurs","pages":["bible-du-lore"]}];
